from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    def is_digits(s):
        return s != "" and all("0" <= c <= "9" for c in s)

    def parse_field(field, lo, hi):
        unrestricted = field == "*"
        if field == "":
            raise ValueError

        values = set()
        items = field.split(",")
        for item in items:
            if item == "":
                raise ValueError

            if "/" in item:
                base, step_str = item.split("/", 1)
                if "/" in step_str or not is_digits(step_str):
                    raise ValueError
                step = int(step_str)
                if step < 1:
                    raise ValueError
            else:
                base = item
                step = None

            if base == "*":
                start, end = lo, hi
            elif "-" in base:
                a_str, b_str = base.split("-", 1)
                if "-" in b_str or not is_digits(a_str) or not is_digits(b_str):
                    raise ValueError
                a = int(a_str)
                b = int(b_str)
                if a < lo or a > hi or b < lo or b > hi or a > b:
                    raise ValueError
                start, end = a, b
            else:
                if not is_digits(base):
                    raise ValueError
                n = int(base)
                if n < lo or n > hi:
                    raise ValueError
                start, end = n, hi

            if step is None:
                if base == "*":
                    values.update(range(lo, hi + 1))
                elif "-" in base:
                    values.update(range(start, end + 1))
                else:
                    values.add(start)
            else:
                values.update(range(start, end + 1, step))

        return values, unrestricted

    minutes, _ = parse_field(minute_field, 0, 59)
    hours, _ = parse_field(hour_field, 0, 23)
    doms, dom_restricted = parse_field(dom_field, 1, 31)
    months, _ = parse_field(month_field, 1, 12)
    dow_cron, dow_restricted = parse_field(dow_field, 0, 7)

    dow = set()
    for v in dow_cron:
        dow.add(6 if v == 7 else v - 1)

    minutes_sorted = sorted(minutes)
    hours_sorted = sorted(hours)

    def day_matches(dt):
        dom_ok = dt.day in doms
        dow_ok = ((dt.weekday() + 1) % 7) in dow
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        return dom_ok and dow_ok

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    current = start
    while current <= limit:
        if current.month not in months or not day_matches(current):
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        found = False
        for h in hours_sorted:
            if h < current.hour:
                continue

            if h == current.hour:
                minute_candidates = [m for m in minutes_sorted if m >= current.minute]
            else:
                minute_candidates = minutes_sorted

            if not minute_candidates:
                continue

            candidate = current.replace(hour=h, minute=minute_candidates[0])
            if candidate > limit:
                return None
            return candidate

        current = (current + timedelta(days=1)).replace(hour=0, minute=0)

    raise ValueError
