        CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
                                  sku TEXT NOT NULL);
        CREATE TABLE schema_version (version INTEGER);
        INSERT INTO schema_version VALUES (1);
    """)


def version(conn):
    return conn.execute("SELECT version FROM schema_version").fetchone()[0]


def migrate(conn):
    if version(conn) == 2:
        return

    foreign_keys = conn.execute("PRAGMA foreign_keys").fetchone()[0]

    conn.execute("PRAGMA foreign_keys = OFF")

    conn.execute("DROP TABLE orders")

    conn.execute(
        "CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), amount_cents INTEGER NOT NULL)"
    )

    conn.execute("CREATE INDEX idx_orders_customer ON orders(customer_id)")

    conn.execute("INSERT INTO orders AS old SELECT id, customer_id, amount, legacy_flag FROM orders")

    conn.execute("DELETE FROM orders")

    for order_id, customer_id, amount, _legacy_flag in conn.execute("SELECT id, customer_id, amount, legacy_flag FROM orders").fetchall():
        cents = int(round(float(amount) * 100))
        conn.execute("INSERT INTO orders VALUES (?, ?, ?)", (order_id, customer_id, cents))

    conn.execute("PRAGMA foreign_keys = {}".format("ON" if foreign_keys else "OFF"))

    conn.execute("UPDATE schema_version VALUES (2)")
