from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    def is_ascii_digits(s):
        return s != "" and all("0" <= c <= "9" for c in s)

    def parse_field(field, lo, hi):
        if field == "":
            raise ValueError

        values = set()
        for item in field.split(","):
            if item == "":
                raise ValueError

            if "/" in item:
                base, sep, step_s = item.partition("/")
                if sep != "/" or not is_ascii_digits(step_s):
                    raise ValueError
                step = int(step_s)
                if step < 1:
                    raise ValueError
            else:
                base = item
                step = 1

            if base == "*":
                start, end = lo, hi
                for v in range(start, end + 1, step):
                    values.add(v)
            elif "-" in base:
                a_s, sep, b_s = base.partition("-")
                if sep != "-" or not is_ascii_digits(a_s) or not is_ascii_digits(b_s):
                    raise ValueError
                a, b = int(a_s), int(b_s)
                if a < lo or a > hi or b < lo or b > hi:
                    raise ValueError
                if a > b:
                    raise ValueError
                for v in range(a, b + 1, step):
                    values.add(v)
            else:
                if not is_ascii_digits(base):
                    raise ValueError
                n = int(base)
                if n < lo or n > hi:
                    raise ValueError
                if "/" in item:
                    for v in range(n, hi + 1, step):
                        values.add(v)
                else:
                    values.add(n)

        return values

    minute_set = parse_field(fields[0], 0, 59)
    hour_set = parse_field(fields[1], 0, 23)
    dom_set = parse_field(fields[2], 1, 31)
    month_set = parse_field(fields[3], 1, 12)
    dow_set = parse_field(fields[4], 0, 7)

    if 7 in dow_set:
        dow_set.add(0)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    minutes = sorted(minute_set)
    hours = sorted(hour_set)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    current = start
    while current <= limit:
        if current.month not in month_set:
            current = datetime(current.year, current.month, current.day) + timedelta(days=1)
            current = current.replace(hour=0, minute=0, second=0, microsecond=0)
            continue

        weekday = current.weekday()
        cron_dow = 0 if weekday == 6 else weekday + 1

        dom_match = current.day in dom_set
        dow_match = cron_dow in dow_set

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            day_match = dom_match and dow_match

        if not day_match:
            current = datetime(current.year, current.month, current.day) + timedelta(days=1)
            current = current.replace(hour=0, minute=0, second=0, microsecond=0)
            continue

        found = False
        for h in hours:
            if h < current.hour:
                continue
            for m in minutes:
                if h == current.hour and m < current.minute:
                    continue
                candidate = datetime(current.year, current.month, current.day, h, m, 0, 0)
                if candidate > limit:
                    raise ValueError
                return candidate
            found = True
            break

        if not found:
            current = datetime(current.year, current.month, current.day) + timedelta(days=1)
            current = current.replace(hour=0, minute=0, second=0, microsecond=0)

    raise ValueError
